using System.ComponentModel.DataAnnotations;
namespace OVI.Modelos.Entidades;

public class Rol { public int IdRol {get;set;} [Required, StringLength(50)] public string Nombre {get;set;} = "Estudiante"; [StringLength(200)] public string? Descripcion {get;set;} public List<Usuario> Usuarios {get;set;} = new(); }
public class Institucion { public int IdInstitucion {get;set;} [Required,StringLength(150)] public string Nombre {get;set;} = "Institución no especificada"; [StringLength(250)] public string? Direccion {get;set;} [StringLength(20)] public string? Telefono {get;set;} public bool Estado {get;set;} = true; public List<Usuario> Usuarios {get;set;} = new(); }
public class Usuario { public int IdUsuario {get;set;} public int IdRol {get;set;} public int IdInstitucion {get;set;} [Required,StringLength(100)] public string Nombre {get;set;} = ""; [Required,StringLength(100)] public string Apellido {get;set;} = ""; [Required,EmailAddress,StringLength(150)] public string Correo {get;set;} = ""; // En producción utilizar ASP.NET Core Identity; nunca guardar contraseñas en texto plano.
 [StringLength(255)] public string? PasswordHash {get;set;} public bool Estado {get;set;} = true; public Rol? Rol {get;set;} public Institucion? Institucion {get;set;} public List<Evaluacion> Evaluaciones {get;set;} = new(); }
public class Evaluacion { public int IdEvaluacion {get;set;} public int IdUsuario {get;set;} public DateTime FechaInicio {get;set;} = DateTime.UtcNow; public DateTime? FechaFin {get;set;} [Required,StringLength(20)] public string Estado {get;set;} = "En proceso"; public Usuario? Usuario {get;set;} public List<Respuesta> Respuestas {get;set;} = new(); public Resultado? Resultado {get;set;} }
public class PreguntaRIASEC { public int IdPregunta {get;set;} [Required,StringLength(500)] public string Enunciado {get;set;} = ""; [Required,StringLength(20)] public string CategoriaRIASEC {get;set;} = "Realista"; public int Valor {get;set;} = 1; public bool Estado {get;set;} = true; public List<Respuesta> Respuestas {get;set;} = new(); }
public class Respuesta { public int IdRespuesta {get;set;} public int IdEvaluacion {get;set;} public int IdPregunta {get;set;} [Required,StringLength(100)] public string OpcionSeleccionada {get;set;} = "Me interesa"; public int Valor {get;set;} public Evaluacion? Evaluacion {get;set;} public PreguntaRIASEC? PreguntaRIASEC {get;set;} }
public class Resultado { public int IdResultado {get;set;} public int IdEvaluacion {get;set;} public int PuntajeR {get;set;} public int PuntajeI {get;set;} public int PuntajeA {get;set;} public int PuntajeS {get;set;} public int PuntajeE {get;set;} public int PuntajeC {get;set;} [Required,StringLength(255)] public string PerfilDominante {get;set;} = ""; public DateTime FechaResultado {get;set;} = DateTime.UtcNow; public Evaluacion? Evaluacion {get;set;} public List<Recomendacion> Recomendaciones {get;set;} = new(); }
public class Carrera { public int IdCarrera {get;set;} [Required,StringLength(150)] public string Nombre {get;set;} = ""; [StringLength(500)] public string? Descripcion {get;set;} [Required,StringLength(50)] public string Tipo {get;set;} = "Universitaria"; [StringLength(150)] public string? Institucion {get;set;} public bool Estado {get;set;} = true; public List<Recomendacion> Recomendaciones {get;set;} = new(); }
public class Recomendacion { public int IdRecomendacion {get;set;} public int IdResultado {get;set;} public int IdCarrera {get;set;} public decimal NivelAfinidad {get;set;} public int Posicion {get;set;} public Resultado? Resultado {get;set;} public Carrera? Carrera {get;set;} }
public class FAQChatbot { public int IdFAQ {get;set;} [Required,StringLength(500)] public string Pregunta {get;set;} = ""; [Required,StringLength(1000)] public string Respuesta {get;set;} = ""; [StringLength(100)] public string? Categoria {get;set;} [StringLength(200)] public string? PalabrasClave {get;set;} public bool Estado {get;set;} = true; }
